from z3 import *

def solve_qg3(n):
    s = Solver()
    x = [Int(f"x_{i}") for i in range(n*n)]

    # Latin square
    for i in range(n):
        s.add(Distinct([x[i*n + j] for j in range(n)]))
        s.add(Distinct([x[j*n + i] for j in range(n)]))
        for j in range(n):
            s.add(x[i*n + j] >= 0, x[i*n + j] < n)

    # Idempotent
    for i in range(n):
        s.add(x[i*n + i] == i)

    # QG3 property: x[x[i][j]][x[j][i]] = i
    # x[i][j] is x[i*n + j]
    # x[j][i] is x[j*n + i]
    # x[x[i][j]][x[j][i]] is x[x[i*n + j] * n + x[j*n + i]]
    # To index with a variable, we can use a helper array or If-Else chains.
    # Or, we can use the `Select` function if we treat the grid as an array.
    # Actually, a simpler way is to use a 2D array of boolean variables:
    # b[i][j][v] is true if x[i][j] == v

    b = [[[Bool(f"b_{i}_{j}_{v}") for v in range(n)] for j in range(n)] for i in range(n)]

    # Each cell has exactly one value
    for i in range(n):
        for j in range(n):
            s.add(Sum([If(b[i][j][v], 1, 0) for v in range(n)]) == 1)

    # Latin square
    for i in range(n):
        for v in range(n):
            s.add(Sum([If(b[i][j][v], 1, 0) for j in range(n)]) == 1)
            s.add(Sum([If(b[j][i][v], 1, 0) for j in range(n)]) == 1)

    # Idempotent
    for i in range(n):
        s.add(b[i][i][i])

    # QG3 property: x[x[i][j]][x[j][i]] = i
    # Let k = x[i][j], l = x[j][i]. Then x[k][l] = i.
    # b[i][j][k] is true, b[j][i][l] is true, b[k][l][i] is true.
    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(n):
                    s.add(Implies(And(b[i][j][k], b[j][i][l]), b[k][l][i]))

    if s.check() == sat:
        m = s.model()
        res = []
        for i in range(n):
            for j in range(n):
                for v in range(n):
                    if is_true(m[b[i][j][v]]):
                        res.append(v)
        return res
    else:
        return None

