import random

def is_latin(grid, n):
    for i in range(n):
        row = [grid[i*n + j] for j in range(n)]
        if len(set(row)) != n: return False
        col = [grid[j*n + i] for j in range(n)]
        if len(set(col)) != n: return False
    return True

def is_idempotent(grid, n):
    for i in range(n):
        if grid[i*n + i] != i: return False
    return True

def is_qg3(grid, n):
    for i in range(n):
        for j in range(n):
            k = grid[i*n + j]
            l = grid[j*n + i]
            if grid[k*n + l] != i: return False
    return True

def solve_backtracking(n):
    grid = [-1] * (n*n)
    for i in range(n):
        grid[i*n + i] = i

    def get_candidates(idx):
        row = idx // n
        col = idx % n
        used = set()
        for i in range(n):
            if grid[row*n + i] != -1: used.add(grid[row*n + i])
            if grid[i*n + col] != -1: used.add(grid[i*n + col])
        return [v for v in range(n) if v not in used]

    def check_partial_qg3(grid, n):
        for i in range(n):
            for j in range(n):
                k = grid[i*n + j]
                l = grid[j*n + i]
                if k != -1 and l != -1:
                    val = grid[k*n + l]
                    if val != -1 and val != i:
                        return False
        return True

    def backtrack(idx):
        if idx == n*n:
            return True

        row = idx // n
        col = idx % n

        if grid[idx] != -1:
            return backtrack(idx + 1)

        for v in get_candidates(idx):
            grid[idx] = v
            if check_partial_qg3(grid, n):
                if backtrack(idx + 1): return True
            grid[idx] = -1
        return False

    if backtrack(0):
        return grid
    return None

